package __PACKAGE__;

import net.minecraft.client.multiplayer.ClientLevel;
import net.minecraft.client.particle.Particle;
import net.minecraft.client.particle.ParticleProvider;
import net.minecraft.util.RandomSource;

/**
 * The client side of Sparkle, shared by the loaders: what a received Sparkle particle does, and the reload of the
 * systems with the resources.
 * Generated by the Sparkle plugin: do not edit, it is written again when the runtime is updated.
 */
public final class SparkleClient {
    private SparkleClient() {
    }

    /** Turns a received {@link SparkleOptions} into a playing system, or stops systems. */
    public static ParticleProvider<SparkleOptions> provider() {
        return SparkleClient::create;
    }

    /** Forgets the systems read: the resources were reloaded. */
    public static void reload() {
        SparkleSystems.clear();
    }

    /** The provider of Minecraft 1.21.9 and later (with a random source). */
    private static Particle create(SparkleOptions options, ClientLevel level, double x, double y, double z, double xd, double yd, double zd,
            RandomSource random) {
        return create(options, level, x, y, z, xd, yd, zd);
    }

    private static Particle create(SparkleOptions options, ClientLevel level, double x, double y, double z, double xd, double yd, double zd) {
        if (options.action() == SparkleOptions.STOP) {
            double radius = 0.0;
            for (SparkleOptions.Parameter parameter : options.parameters()) {
                if (parameter.name().equals("radius")) {
                    radius = parameter.x();
                }
            }

            return SparkleSystemParticle.stop(x, y, z, options.entity(), radius);
        }

        return SparkleSystemParticle.start(level, options, x, y, z);
    }
}
